      "content": "// Cliente de la pasarela de pagos.
const PAYMENTS_API_URL = 'https://api.pagos-demo.example/v1';

if (!process.env.PAYMENTS_API_KEY) {
  throw new Error('PAYMENTS_API_KEY environment variable is required');
}
const PAYMENTS_API_KEY = process.env.PAYMENTS_API_KEY;

export interface ChargeRequest {
  orderId: number;
  amountCents: number;
  currency: 'PEN';
}

export async function charge(req: ChargeRequest): Promise<{ id: string; status: string }> {
  const res = await fetch(`${PAYMENTS_API_URL}/charges`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${PAYMENTS_API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(req),
  });
  if (!res.ok) throw new Error(`payment failed: ${res.status}`);
  return res.json() as Promise<{ id: string; status: string }>;
}
